content.thinking:
`toggleOrientation` calls redrawAll directly. So I can trigger a redraw via `cg.toggleOrientation()`. Also `cg.redrawAll()` directly.

Now, let me first reproduce the bug with a test before fixing. I'll write a test that uses a mock ResizeObserver.

Let me write the test file `tests/dom.test.ts`.

Plan for test:
```ts
import { Chessground } from '../src/chessground';
import { describe, expect, test, vi } from 'vitest';

// build mock ResizeObserver
class MockResizeObserver {
  static instances: MockResizeObserver[] = [];
  observed = new Set<Element>();
  disconnected = false;
  callback: ResizeObserverCallback;
  constructor(cb) { this.callback = cb; MockResizeObserver.instances.push(this); }
  observe(el) { this.observed.add(el); }
  unobserve(el) { this.observed.delete(el); }
  disconnect() { this.disconnected = true; this.observed.clear(); }
}
```

Set `globalThis.ResizeObserver = MockResizeObserver as any`.

Then test:
```ts
test('destroy disconnects the ResizeObserver', () => {
  const wrap = document.createElement('div');
  document.body.appendChild(wrap);
  const cg = Chessground(wrap, { viewOnly: true });
  const ro = MockResizeObserver.instances.at(-1)!;
  expect(ro.disconnected).toBe(false);
  expect(ro.observed.has(wrap)).toBe(true);
  cg.destroy();
  expect(ro.disconnected).toBe(true);
